-- MediGuide-AI medication catalog seed data with common use cases
-- For demo/catalog use only. This is not medical advice and must not be used to prescribe medication.
-- Common use cases are short display labels for a medication tracker UI.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS medication_catalog (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    med_code VARCHAR(20) UNIQUE NOT NULL,
    name VARCHAR(120) NOT NULL,
    generic_name VARCHAR(160),
    category VARCHAR(120),
    form VARCHAR(60),
    default_strength VARCHAR(80),
    route VARCHAR(60),
    rx_required BOOLEAN DEFAULT TRUE,
    common_uses TEXT,
    patient_note TEXT,
    active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE medication_catalog ADD COLUMN IF NOT EXISTS common_uses TEXT;
ALTER TABLE medication_catalog ADD COLUMN IF NOT EXISTS patient_note TEXT;

CREATE INDEX IF NOT EXISTS idx_medication_catalog_name ON medication_catalog (LOWER(name));
CREATE INDEX IF NOT EXISTS idx_medication_catalog_category ON medication_catalog (category);
CREATE INDEX IF NOT EXISTS idx_medication_catalog_common_uses ON medication_catalog USING gin (to_tsvector('english', COALESCE(common_uses, '')));

ON CONFLICT (med_code) DO UPDATE SET
    name = EXCLUDED.name,
    generic_name = EXCLUDED.generic_name,
    category = EXCLUDED.category,
    form = EXCLUDED.form,
    default_strength = EXCLUDED.default_strength,
    route = EXCLUDED.route,
    rx_required = EXCLUDED.rx_required,
    common_uses = EXCLUDED.common_uses,
    patient_note = EXCLUDED.patient_note,
    active = EXCLUDED.active,
    updated_at = NOW();
